from pathlib import Path
from PIL import Image,ImageDraw,ImageFont
import json,base64,html
D=Path(__file__).resolve().parents[1]
try:font=ImageFont.truetype('/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf',23)
except OSError:font=ImageFont.load_default()
for key,title in [('sail-close','Sail Selat Karimata'),('ale-close','Ale-Ale — versi menara jam'),('matan-close','Keraton Matan'),('pulau-datok','Pulau Datok — komposisi pantai'),('kayong-race','Kayong Utara — kamera balapan'),('ketapang-race','Ketapang — kamera balapan'),('matan-race','Keraton Matan — kamera balapan')]:
 im=Image.new('RGB',(1600,560),'#112b40');draw=ImageDraw.Draw(im);draw.text((20,14),title,fill='#fff0ce',font=font)
 for i,label in enumerate(['MODEL LAMA — finalisasi 6J','MODEL BARU — PATCH 8A']):
  draw.text((20+i*800,59),label,fill='#65dfc4',font=font);source=Image.open(D/'screenshots'/('before'if i==0 else'after')/(key+'.png')).convert('RGB');source.thumbnail((790,465));im.paste(source,(i*800+(800-source.width)//2,99))
 im.save(D/'screenshots'/('comparison-'+key+'.jpg'),quality=88,optimize=True)
refs=[{'id':'sail','title':'Sail Selat Karimata','image':'sail-close','source':'https://kalbar.antaranews.com/foto/520877/tugu-sail-selat-karimata/2','features':'Bidang hijau asimetris, lubang bundar, garis putih, panel abu-abu, rangka putih melengkung dan ornamen cokelat; alas putih bundar. Foto kedua lampiran pengguna.'},{'id':'ale','title':'Ale-Ale: versi pada lampiran','image':'ale-close','source':'https://www.beritaketapang.com/gayahidup-kesehatan/2431736077/di-bawah-atap-melayu-di-tengah-cangkang-emas-cerita-dari-tugu-ale-ale-ketapang','features':'Menara jam hijau-kuning, atap Melayu bersilang, dua cangkang pada alas samping. Foto/gambar keempat lampiran; tidak digabung dengan versi 2019.'},{'id':'matan','title':'Keraton Matan','image':'matan-close','source':'https://www.pustaka-bpkxii.org/pustaka/arsitektur-keraton-matan-kabupaten-ketapang','features':'Fasad kuning-hijau, serambi panjang, gable pusat bermahkota dan paviliun terbuka di sudut kanan. Foto ketiga lampiran pengguna.'}]
(D/'references/manifest.json').write_text(json.dumps({'authority':'Images visibly supplied by user in conversation; original image bytes are not exposed as local attachments in this workspace.','web_access':'All four requested pages blocked: CONNECT 403; browser ERR_TUNNEL_CONNECTION_FAILED.','reference_images_embedded':False,'photos':refs,'excluded':'First attachment depicts a mosque, not one of the three target landmarks.','older_ale_source':'https://commons.wikimedia.org/wiki/File:Tugu_Ale-ale_Ketapang_2019.jpg','accuracy_limit':'Visual interpretation from provided views, not measured reconstruction or verified architectural survey.'},indent=2,ensure_ascii=False))
parts=['''<!doctype html><html lang="id"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>BlokRaya PATCH 8A — Foto dan render aktual</title><style>body{margin:0;padding:24px;background:#10283b;color:#ebf4ee;font:16px system-ui}h1{font-size:26px}section{margin:28px 0;padding:18px;background:#1b394c;border-radius:16px}.row{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}article{min-width:0}img{width:100%;aspect-ratio:1.6;object-fit:contain;background:#102332}.reference{min-height:240px;border:1px dashed #66c9b0;padding:12px;border-radius:10px}a{color:#79e6c6}small{display:block;line-height:1.5}input{max-width:100%;margin:12px 0}button{padding:12px;background:#ffb558;border:0;border-radius:10px;cursor:pointer}@media(max-width:800px){.row{grid-template-columns:1fr}}@media print{input,button{display:none}body{background:white;color:black;padding:0}section{break-inside:avoid;background:white}}</style><h1>Foto referensi → Model lama → Model baru</h1><p>Semua gambar model di bawah adalah render engine game pada kamera, pose, dan pencahayaan setara. Tidak ada gambar generatif.</p><p><b>Foto referensi tidak dibundel:</b> gambar terlihat di percakapan, tetapi file aslinya tidak tersedia pada workspace dan halaman sumber ditolak jaringan. Pilih berkas foto lampiran lokal di kolom pertama untuk perbandingan tiga gambar secara offline. Foto yang dipilih tidak diunggah atau disimpan ke server.</p>''']
for ref in refs:
 parts.append('<section><h2>'+html.escape(ref['title'])+'</h2><div class="row"><article><h3>FOTO REFERENSI</h3><div class="reference"><img hidden alt="Foto referensi pilihan pengguna"><input type="file" accept="image/*"><small>'+html.escape(ref['features'])+'</small><p><a href="'+html.escape(ref['source'],quote=True)+'">Sumber yang diminta pengguna</a></p></div></article>')
 for key,label in [('before','MODEL LAMA'),('after','MODEL BARU')]:
  p=D/'screenshots'/key/(ref['image']+'.png');uri='data:image/png;base64,'+base64.b64encode(p.read_bytes()).decode();parts.append('<article><h3>'+label+'</h3><img src="'+uri+'" alt="'+label+' '+html.escape(ref['title'],quote=True)+'"></article>')
 parts.append('</div></section>')
parts.append('''<button onclick="print()">Cetak lembar perbandingan</button><script>document.querySelectorAll('input').forEach(f=>f.onchange=()=>{const file=f.files[0];if(!file)return;const img=f.previousElementSibling;if(img.dataset.url)URL.revokeObjectURL(img.dataset.url);img.dataset.url=URL.createObjectURL(file);img.src=img.dataset.url;img.hidden=false});</script></html>''')
(D/'photo-model-review.html').write_text(''.join(parts))
print('Generated seven before/after sheets and an offline photo/model review; no missing photo fabricated.')
